std::vector<unsigned char> expected_text() {
  std::vector<unsigned char> v;
  const char* s = "The quick brown fox jumps over the lazy dog. ";
  for (int i = 0; i < 40; ++i) v.insert(v.end(), s, s + std::strlen(s));
  return v;
}

TEST(inflate_blocks) {
  std::vector<unsigned char> out(4096);
  size_t n = 0;
  CHECK(inflate_raw(k_stored, sizeof k_stored, out.data(), out.size(), n) == InflateResult::Ok);
  CHECK(n == sizeof kRandom && std::memcmp(out.data(), kRandom, n) == 0);
  CHECK(inflate_raw(k_fixed, sizeof k_fixed, out.data(), out.size(), n) == InflateResult::Ok);
  const char* fixed = "abcabcabcabcabcabc hello hello hello";
  CHECK(n == std::strlen(fixed) && std::memcmp(out.data(), fixed, n) == 0);
  const auto text = expected_text();
  CHECK(inflate_raw(k_dynamic, sizeof k_dynamic, out.data(), out.size(), n) == InflateResult::Ok);
  CHECK(n == text.size() && std::memcmp(out.data(), text.data(), n) == 0);
  CHECK(inflate_auto(k_zlib, sizeof k_zlib, out.data(), out.size(), n) == InflateResult::Ok);
  CHECK(n == text.size() && std::memcmp(out.data(), text.data(), n) == 0);
  CHECK(inflate_auto(k_dynamic, sizeof k_dynamic, out.data(), out.size(), n) == InflateResult::Ok && n == text.size());
}

TEST(inflate_errors) {
  std::vector<unsigned char> out(4096);
  size_t n = 0;
  CHECK(inflate_raw(k_dynamic, sizeof k_dynamic, out.data(), 100, n) == InflateResult::OutputFull);
  CHECK(inflate_raw(k_dynamic, 10, out.data(), out.size(), n) == InflateResult::Truncated);
  const unsigned char bad[] = {0x07, 0xff, 0xff};  // block type 3 is reserved
  CHECK(inflate_raw(bad, sizeof bad, out.data(), out.size(), n) == InflateResult::BadData);
}
